import{_ as e,o as t,c as r,a4 as o}from"./chunks/framework.9tZL7ZIQ.js";const h=JSON.parse('{"title":"巴里·塔特尔曼","description":"","frontmatter":{"title":"巴里·塔特尔曼","date":"2026-04-13T00:00:00.000Z"},"headers":[],"relativePath":"04_people/巴里·塔特尔曼.md","filePath":"04_people/巴里·塔特尔曼.md"}'),l={name:"04_people/巴里·塔特尔曼.md"};function i(n,a,s,_,d,p){return t(),r("div",null,[...a[0]||(a[0]=[o('<h1 id="巴里·塔特尔曼" tabindex="-1">巴里·塔特尔曼 <a class="header-anchor" href="#巴里·塔特尔曼" aria-label="Permalink to &quot;巴里·塔特尔曼&quot;">​</a></h1><ul><li><strong>角色职位</strong>：乔丹家具（Jordan Furniture）创始人</li><li><strong>与巴菲特关系</strong>：将乔丹家具带入伯克希尔·哈撒韦收购视野的企业创始人</li></ul><h2 id="主要事迹" tabindex="-1">主要事迹 <a class="header-anchor" href="#主要事迹" aria-label="Permalink to &quot;主要事迹&quot;">​</a></h2><p>巴里·塔特尔曼是乔丹家具（Jordan Furniture）的创始人。乔丹家具是美国东北部地区知名的家具零售商，在新英格兰地区拥有多家门店，以其优质的服务和丰富的产品线著称。塔特尔曼作为创始人，从一家地方家具店起步，凭借对本地市场的深刻理解和真诚的经营理念，逐步将乔丹家具打造为区域市场的领先品牌。</p><p>乔丹家具的经营风格以顾客导向著称，塔特尔曼强调与顾客建立长期信任关系，而非追求短期交易最大化。这种价值观与巴菲特选股时看重&quot;受尊敬的管理层和经久不衰的品牌声誉&quot;高度一致。乔丹家具最终进入伯克希尔的收购视野，正是巴菲特在消费零售领域持续寻找优质标的的结果。</p><p>作为创始人，塔特尔曼在乔丹家具被收购后继续发挥重要作用，确保了公司文化的延续和员工队伍的稳定。伯克希尔收购后通常保留原有的管理团队，这一做法在乔丹家具案例中也得到了体现，使得公司在过渡期保持平稳运营，继续服务其在新英格兰地区的忠实顾客群体。</p><h2 id="关键年份事件" tabindex="-1">关键年份事件 <a class="header-anchor" href="#关键年份事件" aria-label="Permalink to &quot;关键年份事件&quot;">​</a></h2><ul><li><strong>创立期</strong>：创立乔丹家具，逐步发展成新英格兰地区领先的家具零售商</li><li><strong>被收购期</strong>：乔丹家具被伯克希尔·哈撒韦收购，成为伯克希尔消费板块的一部分</li><li><strong>持续经营期</strong>：在伯克希尔控股下，乔丹家具保持品牌独立运营，服务区域市场顾客</li></ul><h2 id="关键原文出处" tabindex="-1">关键原文出处 <a class="header-anchor" href="#关键原文出处" aria-label="Permalink to &quot;关键原文出处&quot;">​</a></h2><p>以下为该人物在致股东信中被提及的关键年份，点击即可阅读完整翻译：</p><ul><li><a href="/search?q=巴里·塔特尔曼在1999年股东信中的原话">1999年：完整翻译|/01_letters/1999年/翻译</a></li></ul>',11)])])}const c=e(l,[["render",i]]);export{h as __pageData,c as default};
